import { EMPTY_OBJ, IS_NON_DIMENSIONAL } from '../constants';
import options from '../options';
import { assign } from '../util';

/**
 * Diff the old and new properties of a VNode and apply changes to the DOM node
 * @param {import('../internal').PreactElement} dom The DOM node to apply
 * changes to
 * @param {object} newProps The new props
 * @param {object} oldProps The old props
 * @param {boolean} isSvg Whether or not this node is an SVG node
 * @param {boolean} hydrate Whether or not we are in hydration mode
 */
export function diffProps(dom, newProps, oldProps, isSvg, hydrate) {
	let i;

	for (i in oldProps) {
		if (i !== 'children' && i !== 'key' && !(i in newProps)) {
			setProperty(dom, i, null, oldProps[i], isSvg);
		}
	}

	for (i in newProps) {
		if (
			(!hydrate || typeof newProps[i] == 'function') &&
			i !== 'children' &&
			i !== 'key' &&
			i !== 'value' &&
			i !== 'checked' &&
			oldProps[i] !== newProps[i]
		) {
			setProperty(dom, i, newProps[i], oldProps[i], isSvg);
		}
	}
}

function setStyle(style, key, value) {
	if (key[0] === '-') {
		style.setProperty(key, value);
	} else if (value == null) {
		style[key] = '';
	} else if (typeof value != 'number' || IS_NON_DIMENSIONAL.test(key)) {
		style[key] = value;
	} else {
		style[key] = value + 'px';
	}
}

function applyStyleDiff(dom, value, oldValue) {
	if (typeof value == 'string') {
		dom.style.cssText = value;
	} else {
		if (typeof oldValue == 'string') {
			dom.style.cssText = oldValue = '';
		}

		if (oldValue) {
			for (let name in oldValue) {
				if (!(value && name in value)) {
					setStyle(dom.style, name, '');
				}
			}
		}

		if (value) {
			for (let name in value) {
				if (!oldValue || value[name] !== oldValue[name]) {
					setStyle(dom.style, name, value[name]);
				}
			}
		}
	}
}

function setDomAttribute(dom, name, value) {
	let xlinkName;
	let xlinkRef;
	let shouldRemoveAttribute;

	if (typeof value == 'function') {
		return;
	}

	if (name === 'dangerouslySetInnerHTML') {
		return;
	}

	xlinkRef = 'http://www.w3.org/1999/xlink';
	xlinkName = name.replace(/xlink:?/, '');
	if (name !== xlinkName) {
		shouldRemoveAttribute = false;
		if (value == null || value === false) {
			shouldRemoveAttribute = true;
		}
		if (shouldRemoveAttribute) {
			dom.removeAttributeNS(xlinkRef, xlinkName.toLowerCase());
		} else {
			dom.setAttributeNS(xlinkRef, xlinkName.toLowerCase(), value);
		}
		return;
	}

	shouldRemoveAttribute = false;
	if (value == null) {
		shouldRemoveAttribute = true;
	} else if (value === false) {
		// ARIA-attributes have a different notion of boolean values.
		// The value `false` is different from the attribute not
		// existing on the DOM, so we can't remove it. For non-boolean
		// ARIA-attributes we could treat false as a removal, but the
		// amount of exceptions would cost us too many bytes. On top of
		// that other VDOM frameworks also always stringify `false`.
		if (!/^ar/.test(name)) {
			shouldRemoveAttribute = true;
		}
	}

	if (shouldRemoveAttribute) {
		dom.removeAttribute(name);
	} else {
		dom.setAttribute(name, value);
	}
}

/**
 * Set a property value on a DOM node
 * @param {import('../internal').PreactElement} dom The DOM node to modify
 * @param {string} name The name of the property to set
 * @param {*} value The value to set the property to
 * @param {*} oldValue The old value the property had
 * @param {boolean} isSvg Whether or not this DOM node is an SVG node or not
 */
export function setProperty(dom, name, value, oldValue, isSvg) {
	let useCapture;
	let nameLower;
	let proxy;
	let eventName;
	let listeners;
	let skipDomProperty;
	let nextPropertyValue;
	let propertyExceptions;

	if (isSvg) {
		if (name == 'className') {
			name = 'class';
		}
	}

	if (name === 'style') {
		applyStyleDiff(dom, value, oldValue);
		return;
	}

	// Benchmark for comparison: https://esbench.com/bench/574c954bdb965b9a00965ac6
	if (name[0] === 'o') {
		if (name[1] === 'n') {
			useCapture = name !== (name = name.replace(/Capture$/, ''));
			nameLower = name.toLowerCase();
			if (nameLower in dom) {
				name = nameLower;
			}
			eventName = name.slice(2);
			listeners = dom._listeners;
			if (!listeners) {
				listeners = assign({}, EMPTY_OBJ);
				dom._listeners = listeners;
			}
			listeners[eventName + useCapture] = value;
			proxy = eventProxy;
			if (useCapture) {
				proxy = eventProxyCapture;
			}
			if (value) {
				if (!oldValue) {
					dom.addEventListener(eventName, proxy, useCapture);
				}
			} else {
				dom.removeEventListener(eventName, proxy, useCapture);
			}
			return;
		}
	}

	// HTMLButtonElement.form and HTMLInputElement.form are read-only but can be set using
	// setAttribute. The same is true for several other DOM properties that must stay
	// as attributes to preserve browser behavior.
	propertyExceptions = assign(Object.create(null), EMPTY_OBJ);
	propertyExceptions.list = 1;
	propertyExceptions.tagName = 1;
	propertyExceptions.form = 1;
	propertyExceptions.type = 1;
	propertyExceptions.size = 1;
	propertyExceptions.download = 1;
	propertyExceptions.href = 1;

	skipDomProperty = isSvg;
	if (name in propertyExceptions) {
		skipDomProperty = true;
	}

	if (!skipDomProperty) {
		if (name in dom) {
			nextPropertyValue = value;
			if (value == null) {
				nextPropertyValue = '';
			}
			dom[name] = nextPropertyValue;
			return;
		}
	}

	setDomAttribute(dom, name, value);
}

/**
 * Proxy an event to hooked event handlers
 * @param {Event} e The event object from the browser
 * @private
 */
function eventProxy(e) {
	this._listeners[e.type + false](options.event ? options.event(e) : e);
}

function eventProxyCapture(e) {
	this._listeners[e.type + true](options.event ? options.event(e) : e);
}

